/** 隔离契约：真实客户端格式、文件保留、进程状态和JSON-RPC握手。绝不改用户载体。 */
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import crypto from 'node:crypto';import {spawn} from 'node:child_process';import {fileURLToPath} from 'node:url';
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'connect-contract-'));process.env.MEMORY_DB=path.join(tmp,'data/test.db');process.env.EMBED_MODE='fake';fs.mkdirSync(path.dirname(process.env.MEMORY_DB),{recursive:true});
const {carrierFor,connectGuide,writeConnection,readCarrier,parseJsonConfig,canonicalEntry}=await import('./agent-adapters.js');
const {discoverInstalledAgents}=await import('./agent-discovery.js');const {installConnectionState,saveConnectionPulse,runtimeFor,configHash}=await import('./connection-runtime.js');const {probeConnection}=await import('./connection-probe.js');
const {openDb}=await import('./db.js');const db=openDb(process.env.MEMORY_DB);installConnectionState(db);
let n=0;function check(name,fn){fn();n++;console.log('通过 '+name);}const node=process.execPath,server=fileURLToPath(new URL('./server.js',import.meta.url));
const opts={home:tmp,dbPath:process.env.MEMORY_DB,serverPath:server,nodePath:node,backupDir:path.join(tmp,'backups')};
function file(rel,text){const p=path.join(tmp,rel);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,text);return p;}
try{
 const adapters=['claude','claude-desktop','workbuddy','workbuddy-ai','qoder','zcode','minimax','opencode','vscode','cursor','windsurf','gemini','qwen','traecode','traework','copilot','pi-agent','commandcode','antigravity','mimo'];
 for(const id of adapters){const a={id,name:id};const g=connectGuide(a,{},opts);check(id+'预览为可解析JSON',()=>assert.ok(parseJsonConfig(g.fileSnippet)));const r=writeConnection(a,opts);check(id+'配置写入并回读',()=>{assert.ok(r.ok);assert.ok(readCarrier(carrierFor(a,tmp).file,{},carrierFor(a,tmp).kind).declares);});check(id+'使用绝对Node和实际库',()=>{const f=readCarrier(carrierFor(a,tmp).file,{},carrierFor(a,tmp).kind);assert.equal(f.command,node);assert.equal(f.carrierDb,opts.dbPath);assert.equal(f.env.MEMORY_AGENT_FPATH,carrierFor(a,tmp).file);});check(id+'重复写入幂等',()=>assert.equal(writeConnection(a,opts).unchanged,true));}
 const ca={id:'codex',name:'Codex'},cf=carrierFor(ca,tmp).file;file(path.relative(tmp,cf),'model = "keep-model"\n[projects."C:/my[path]"]\ntrust_level = "trusted"\n[mcp_servers.memoryhub]\ncommand="node"\nargs=[\n"'+server.replaceAll('\\','/')+'"\n]\nstartup_timeout_sec=35\n[mcp_servers.memoryhub.env]\nMEMORY_DB="'+opts.dbPath.replaceAll('\\','/')+'"\nKEEP_SECRET="must-stay-private"\n[other]\nvalue="preserve"\n');
 let r=writeConnection(ca,opts);check('Codex嵌套env及多行数组可修复',()=>assert.ok(r.ok));let f=readCarrier(cf);check('Codex仍只有一个服务器段',()=>assert.equal((fs.readFileSync(cf,'utf8').match(/\[mcp_servers\.memoryhub\]/g)||[]).length,1));check('Codex其它项目和表不变',()=>{const t=fs.readFileSync(cf,'utf8');assert.ok(t.includes('[projects."C:/my[path]"]'));assert.ok(t.includes('[other]\nvalue="preserve"'));assert.ok(t.includes('startup_timeout_sec = 35'));});check('Codex环境凭据保留而预览不泄露',()=>{assert.equal(f.env.KEEP_SECRET,'must-stay-private');assert.ok(!connectGuide(ca,{},opts).fileSnippet.includes('must-stay-private'));});
 const a={id:'claude',name:'Claude'},af=carrierFor(a,tmp).file;
 const original='{// comment stays\n"theme":"keep", /* comment before comma */\n"mcpServers":{"other":{"command":"other","env":{"API_KEY":"private-other"}}},\n}';fs.writeFileSync(af,original);r=writeConnection(a,opts);check('JSONC注释和其它server保留',()=>{assert.ok(r.ok);const t=fs.readFileSync(af,'utf8');assert.ok(t.includes('// comment stays'));assert.equal(parseJsonConfig(t).mcpServers.other.env.API_KEY,'private-other');assert.equal(parseJsonConfig(t).theme,'keep');});check('预览不暴露其它server凭据',()=>assert.ok(!connectGuide(a,{},opts).fileSnippet.includes('private-other')));
 fs.writeFileSync(af,'{"theme":1 /* before comma */,\n}');check('注释位于尾逗号前仍正确合并',()=>assert.ok(writeConnection(a,opts).ok));
 fs.writeFileSync(af,'{"broken":');check('坏JSON不覆盖',()=>{assert.equal(writeConnection(a,opts).ok,false);assert.equal(fs.readFileSync(af,'utf8'),'{"broken":');});
 const disabled={mcpServers:{memoryos:{command:node,args:[server],env:{MEMORY_DB:opts.dbPath},enabled:false}}};fs.writeFileSync(af,JSON.stringify(disabled));check('自动接入保留主动禁用',()=>{assert.equal(writeConnection(a,{...opts,automatic:true}).skipped,true);assert.equal(parseJsonConfig(fs.readFileSync(af,'utf8')).mcpServers.memoryos.enabled,false);});
 fs.writeFileSync(af,JSON.stringify({mcpServers:{memoryos:{command:node,args:[server],env:{MEMORY_DB:path.join(tmp,'other.db')}}}}));check('自动接入不切换其它库',()=>assert.equal(writeConnection(a,{...opts,automatic:true}).skipped,true));
 fs.writeFileSync(af,JSON.stringify({mcpServers:{memoryos:{url:'https://remote.invalid/mcp',type:'http'}}}));check('远程配置不被替换',()=>assert.equal(writeConnection(a,{...opts,automatic:true}).ok,false));
 for(const field of ['serverUrl','httpUrl']){fs.writeFileSync(af,JSON.stringify({mcpServers:{memoryos:{[field]:'https://remote.invalid/mcp'}}}));check(field+'远程配置不被替换',()=>assert.equal(writeConnection(a,{...opts,automatic:true}).ok,false));}
 const pi={id:'pi-agent',name:'Pi'},pif=carrierFor(pi,tmp).file;fs.writeFileSync(pif,'{// legacy comment\n"memoryos":{"command":"node","args":["old/server.js"],"env":{"KEEP":"old"}}\n}');r=writeConnection(pi,opts);check('Pi旧裸映射迁移为真实客户端格式',()=>{assert.ok(r.ok);const t=fs.readFileSync(pif,'utf8');assert.ok(t.includes('// legacy comment'));const v=parseJsonConfig(t);assert.equal(v.mcpServers.memoryos.env.KEEP,'old');assert.equal(v.memoryos,undefined);});
 const oc=readCarrier(carrierFor({id:'opencode'},tmp).file);check('OpenCode使用command数组与environment',()=>{assert.ok(Array.isArray(oc.entry.command));assert.ok(oc.entry.environment);assert.equal(oc.entry.args,undefined);assert.equal(oc.entry.env,undefined);});
 const unsupported=connectGuide({id:'unknown-agent',name:'Unknown'}, {},opts);check('未知载体不伪造可粘贴JSON',()=>{assert.equal(unsupported.canAutoWrite,false);assert.equal(unsupported.manualSnippet,null);});
 file('AppData/Local/Programs/WorkBuddyAI/WorkBuddy.exe','exe');file('AppData/Local/Programs/WorkBuddyAI/RepairApp.exe','repair');file('AppData/Local/Programs/Qoder/Qoder.exe','exe');file('.codex-session-delete/settings.json','{"mcpServers":{"memoryos":{}}}');file('.agents/fake','');file('.agent-browser/fake','');
 const desktop=file('WindowsApps/Claude/app/Claude.exe','exe');const installed=discoverInstalledAgents({home:tmp,platform:'win32',commands:{},systemInventory:{items:[{label:'Claude',path:desktop,source:'运行进程'}]}});
 check('发现WorkBuddyAI真实exe而非RepairApp',()=>assert.match(installed.agents.find(a=>a.id==='workbuddy-ai').path,/WorkBuddy\.exe$/));check('系统进程发现商店版Claude',()=>assert.equal(installed.agents.find(a=>a.id==='claude-desktop').installed,true));check('配置目录不冒充安装',()=>assert.equal(installed.agents.find(a=>a.id==='codex').installed,false));check('备份和技能目录不成为Agent',()=>assert.ok(!installed.agents.some(a=>['codex-session-delete','agents','agent-browser'].includes(a.id))));
 const cid=crypto.randomUUID();saveConnectionPulse(db,{connectionId:cid,agent:'qoder',pid:process.pid,transport:'direct',configFile:carrierFor({id:'qoder'},tmp).file,configHash:configHash(carrierFor({id:'qoder'},tmp).file),dbPath:opts.dbPath,phase:'starting'});check('进程启动与握手就绪分开',()=>{const rt=runtimeFor(db,{id:'qoder'});assert.equal(rt.online,true);assert.equal(rt.phase,'starting');});
 saveConnectionPulse(db,{connectionId:cid,agent:'qoder',pid:process.pid,transport:'direct',dbPath:opts.dbPath,phase:'ready',lastCallAt:new Date().toISOString(),lastTool:'memory_read'});check('真实回报包含实际库及最后调用',()=>{const rt=runtimeFor(db,{id:'qoder'});assert.equal(rt.dbPath,opts.dbPath);assert.equal(rt.lastTool,'memory_read');});
 fs.appendFileSync(carrierFor({id:'qoder'},tmp).file,'\n');check('配置改变提示旧会话重载',()=>assert.equal(runtimeFor(db,{id:'qoder'}).configChanged,true));db.prepare("UPDATE mcp_client_connections SET last_seen='2000-01-01T00:00:00Z' WHERE connection_id=?").run(cid);check('心跳超时不显示在线',()=>assert.equal(runtimeFor(db,{id:'qoder'}).online,false));
 // 按测试载体启动真实MCP进程，完成三段协议并核验数据库；无list-tools替代。
 const probeFile=file('probe.json',JSON.stringify({mcpServers:{memoryos:{command:node,args:[server],env:{MEMORY_DB:opts.dbPath,MEMORY_AGENT:'probe-agent',MEMORYOS_MCP_MODE:'direct',EMBED_MODE:'fake'}}}}));
 const probe=await probeConnection({id:'qoder',name:'Qoder',configFile:probeFile},{expectedDb:opts.dbPath});check('真实MCP初始化枚举与工具调用',()=>{assert.equal(probe.ok,true,JSON.stringify(probe));assert.equal(probe.protocolVerified,true);assert.equal(probe.dbPath,opts.dbPath);});check('探测不制造真实客户端在线记录',()=>assert.equal(db.prepare("SELECT count(*) n FROM mcp_client_connections WHERE agent='probe-agent'").get().n,0));
 const badProbe=await probeConnection({id:'qoder-bad',name:'bad',configFile:file('bad-launch.json','{"mcpServers":{"memoryos":{"command":"missing-node","args":["missing/server.js"]}}}')},{timeoutMs:1000,expectedDb:opts.dbPath});check('错误启动命令显示失败阶段',()=>{assert.equal(badProbe.ok,false);assert.equal(badProbe.stage,'launch');});
 console.log(`总计 ${n} 项通过；隔离目录 ${tmp}`);
}finally{db.close();}
